const updateInvoice = `-- name: UpdateInvoice :exec
UPDATE invoice
SET
    note = IF(?, NULL, COALESCE(?, note)),
    has_been_sent = COALESCE(?, has_been_sent),
    is_edi_sent = COALESCE(?, is_edi_sent),
    is_paid_in_full = COALESCE(?, is_paid_in_full),
    updated_at = CURRENT_TIMESTAMP(3)
WHERE id = ?
AND account_id = ?
`

type UpdateInvoiceParams struct {
	ClearNote    interface{}
	Note         interface{}
	HasBeenSent  sql.NullBool
	IsEdiSent    sql.NullBool
	IsPaidInFull sql.NullBool
	ID           string
	AccountID    string
}

func (q *Queries) UpdateInvoice(ctx context.Context, arg UpdateInvoiceParams) error {
	_, err := q.db.ExecContext(ctx, updateInvoice,
		arg.ClearNote,
		arg.Note,
		arg.HasBeenSent,
		arg.IsEdiSent,
		arg.IsPaidInFull,
		arg.ID,
		arg.AccountID,
	)
	return err
}
